"use strict";
const pictureStories=[
 {id:'one-seventeen',title:'凌晨一点十七分，你怎么还没睡',image:'night',tag:'雨夜',date:'2004.08',intro:'电池剩两格，故事还剩一页。',text:[
 '窗帘缝里漏进一条路灯的光。你把被角往上拉了拉，手机屏幕调到最暗，还是亮得像一小块白天。客厅的钟走一下，你就停一下，确认门外没有脚步声，再按“下一页”。',
 '那时候网页很轻，等待却很长。屏幕下面写着“正在连接”，一圈小点转了又转。你怕流量超了，也怕刚看到的那一页再也打不开，于是把最喜欢的句子抄在作业本背面，字越写越小。',
 '聊天窗口里，那个人的头像已经灰了。十分钟前他说“我睡了，明天见”，你回了一个笑脸，又补了一句“嗯”。发送以后，你盯着那个“嗯”看了半天，觉得它太短，却想不出还能加些什么。',
 '雨敲在窗台上，不急不慢。耳机里是一段听了许多遍的旋律，手机还在掌心微微发热。网页里的故事写到一座车站，有人等了最后一班车，也没有等到想见的人。你忽然很想知道，那个说要睡觉的人，此刻是不是真的睡着了。',
 '你打开短信，打下“下雨了”。看了看，又删掉。最后只留下一行：“明天记得带伞。”收件人已经选好，拇指在发送键上停了很久，还是按了返回。短信留在草稿箱，像一封没有寄出的信。',
 '凌晨一点十七分，手机提醒电量不足。你把充电线从床缝里摸出来，接头插了两次才对。屏幕重新亮起来的那一刻，你又点开了刚才没有看完的故事。',
 '很多年后，你已经记不起那篇文章的名字，也找不到那个灰色头像。可你仍记得雨声、被窝里闷热的空气，以及那块小小屏幕照在手指上的蓝光。',
 '原来你怀念的，不只是一部手机。是那时总觉得，明天还很长。'
 ]},
 {id:'last-class',title:'晚自习以后，操场还亮着',image:'campus',tag:'校园',date:'2005.06',intro:'后来很多夏天，都像那个夏天的回声。',text:[
 '下课铃响的时候，班里没有马上热闹起来。电风扇还在头顶慢慢转，窗外的天已经变成深蓝色。值日生拎起水桶，你把卷子折了两折，夹进那本封面已经起毛的小说里。',
 '他在走廊尽头等你，手里转着自行车钥匙。“走不走？”他说。你说等一下，又回头看了看黑板右上角的倒计时。那个数字一天比一天小，可谁也没有认真想过，归零以后会怎么样。',
 '篮球场上还有人。球砸在地上的声音，隔着半个操场传来，闷闷的。你们沿着跑道往校门口走，聊一道没做出来的数学题，聊新出的歌，聊隔壁班谁又换了一个特别长的网名。',
 '学校门口的小卖部亮着白色灯管。老板把冰柜打开，一股凉气冒出来。你们凑了零钱，买了两根冰棒。他把最后一枚硬币塞进电话机，给家里说：“快到了。”',
 '那时的手机藏在书包最里面，来短信时不敢开声音。你把屏幕藏在课本下面，看见朋友发来一张压得很糊的夕阳图片，下面只有四个字：“明天加油。”你把它保存了，文件名是一串看不懂的数字。',
 '快到岔路口，你们同时慢下来。他说暑假一起去城里买书，你说好。他说下学期要换靠窗的位置，你也说好。好多随口答应的事，就这样被放进了夏天。',
 '毕业以后，那家小卖部换了招牌，操场重新铺了地，教室里的风扇也不再是记忆中的样子。你偶尔路过，还是会朝二楼最右边的窗户看一眼。',
 '有些地方之所以舍不得，是因为你曾经在那里，毫无察觉地度过了最后一次平常的晚上。'
 ]},
 {id:'last-bus',title:'最后一班车，留了一盏灯',image:'station',tag:'远方',date:'2003.09',intro:'你说到站就发短信，我就一直等着。',text:[
 '候车室的灯有一盏坏了，忽明忽暗。你坐在塑料椅上，脚边放着一只旧旅行箱。票是下午买的，薄薄一张，夹在手里已经有了折痕。广播把同一句话念了两遍，你只听清了目的地。',
 '这是你第一次一个人去那么远的地方。家里人一路送到站口，替你数行李，问你有没有带水。你觉得他们说得太多，嘴上一直答应，眼睛却不肯抬起来。',
 '开车前十分钟，手机响了。屏幕上是一个很熟悉的号码。“别忘了吃饭，到了说一声。”短信很短，没有标点。你回：“知道了。”想了想，又添了一个笑脸。',
 '车窗有些脏，外面的灯被水汽晕成一团。你看见送你的人还站在栏杆后面，手里提着刚才没来得及给你的袋子。车慢慢往前挪，你才发现，里面装着的是你小时候最爱吃的那种饼。',
 '手机信号时有时无。你把刚才的短信打开，又关上。路过收费站的时候，远处有一排亮着灯的房子，每一扇窗里，似乎都有人在等另一个人回去。',
 '凌晨，车在服务区停下来。你买了一杯很烫的水，给家里发了条短信：“还在路上，挺好的。”过了一会儿收到回复：“好。”你忽然知道，原来他们也一直没有睡。',
 '天快亮的时候，陌生城市的轮廓从雾里显出来。你拖着箱子下车，站在人群中，第一件事是掏出手机。那条“我到了”发出去以后，你才觉得这趟路真的走完了。',
 '后来你走过更多地方，换过很多号码。可每次抵达，你还是习惯发一条消息。世界很大，报平安的那几个字，却总能把人带回家。'
 ]}
];
pictureStories.push({id:'shared-earphones',title:'把耳机分你一半，把夏天留在这里',image:'portrait',tag:'美女壁纸',date:'2000年代',intro:'那张存过很多次的图片，像一个没有结束的夏天。',text:[
'放学以后，她常常从那条有树荫的小路经过。耳机线垂在浅色外套外面，手里握着一只小小的播放器。我们那时不知道什么叫氛围感，只觉得阳光落在树叶上的样子，特别适合配一首轻轻的歌。',
'后来你在一个图片站里看见一张很像那个下午的照片。网页上方写着“精选壁纸”，下面一排很小的分类：风景、人物、心情、动漫。你把页面翻了好几遍，最后还是点回第一张，按下“保存图片”。',
'手机内存并不大。为了给它腾地方，你删掉了一段已经听腻的铃声，又删了一张不知道什么时候拍糊的照片。保存成功以后，你把它设成待机画面，锁屏，再解锁，反复看了几次，觉得这部用了很久的手机，好像忽然变新了一点。',
'那时候的图片总是小小的。脸庞有些模糊，背景也不清楚，可你会替它补上一整段故事：她刚刚结束一场考试，准备去见一个朋友；或者只是经过一条普通的小路，正好听见自己喜欢的那首歌。',
'朋友问你：“这是谁？”你说不知道，只是在网上存的一张图。他看了一眼，说挺好看的，又低头忙自己的游戏。你没说的是，那张图让你想起很久以前一个不必赶路的下午。',
'再后来，手机换了，存储卡也找不到了。那些文件名是一串数字的图片，一起消失在不知道哪一次搬家里。你记不清照片里的衣服颜色，却一直记得那种干净、缓慢的心情。',
'如果今天再选一张壁纸，你可能不会再选同样的图。但你还是想把耳机分给一个人，沿着有树荫的小路慢慢走，不着急发消息，也不着急抵达什么地方。',
'这张人物配图为AI辅助创作，展示的是成年人物，不对应真实旧站照片或某位明星。故事也是新写的。愿它能让你想起自己的那个夏天。'
]});
let galleryQuery='',galleryTag='全部',galleryNight=false,phonePicture=null,phonePicturePage=0;
function filteredPictures(){const q=galleryQuery.trim().toLowerCase();return pictureStories.filter(s=>(galleryTag==='全部'||s.tag===galleryTag)&&(!q||[s.title,s.tag,s.intro,...s.text].join(' ').toLowerCase().includes(q)));}
function openMemoryGallery(){navigate({type:'pictures',name:'深夜图文馆',url:'archaeo://pictures'});}
function openPictureStory(id){if(!pictureStories.some(s=>s.id===id))return;navigate({type:'picturestory',story:id,name:pictureStories.find(s=>s.id===id).title,url:'archaeo://pictures/'+id});}
function renderMemoryGallery(){const list=filteredPictures();return `<section class="memory-gallery ${galleryNight?'after-midnight':''}"><div class="memory-utility"><button data-action="home">‹ 时光首页</button><button data-phone-gallery>装进旧手机</button><button data-memory-night>${galleryNight?'开灯':'熄灯看图'}</button></div><header><small>01:17 / 那些舍不得关掉的网页</small><h1>深夜图文馆<span>图片里，藏着一个故事。</span></h1><p>雨声、晚自习、最后一班车。点开一张图，慢慢读。</p></header><form id="memory-search"><label for="memory-query">搜一段记忆</label><input id="memory-query" value="${escapeHTML(galleryQuery)}" placeholder="雨夜、校园、短信、远方…" maxlength="80"><button>搜图片 / 故事</button></form><nav class="memory-tags" aria-label="筛选图文">${['全部','雨夜','校园','远方','美女壁纸'].map(t=>`<button data-memory-tag="${t}" aria-pressed="${galleryTag===t}" class="${galleryTag===t?'selected':''}">${t}</button>`).join('')}<span>${list.length} 个图文故事</span></nav><div class="memory-picture-grid">${list.map(s=>`<button class="memory-picture-card" data-picture-story="${s.id}"><div><img src="images/memories/${s.image}.jpg" alt="${escapeHTML(s.title)}的怀旧创作配图" loading="lazy"><span>图文 / ${s.tag}</span></div><small>${s.date} · 怀旧原创</small><h2>${escapeHTML(s.title)}</h2><p>${escapeHTML(s.intro)}</p><b>点击图片，进入故事 &gt;&gt;</b></button>`).join('')||'<div class="memory-empty"><p>没有找到这段记忆。试试“雨夜”“校园”或“短信”。</p><button data-memory-clear>清除筛选，看看全部故事</button></div>'}</div><footer>配图为 AI 辅助创作，故事为本站原创；并非历史照片、旧站原帖或真实人物经历。</footer></section>`;}
function renderPictureStory(page){const s=pictureStories.find(x=>x.id===page.story);if(!s)return '<p>没有找到这个故事。</p>';return `<article class="picture-story ${galleryNight?'after-midnight':''}"><nav><button data-memory-gallery>‹ 图文目录</button><button data-memory-night>${galleryNight?'开灯':'熄灯'}</button><button data-phone-picture="${s.id}">用旧手机读</button><button data-capture-view>保存这一页</button></nav><header><small>夜读 / ${s.tag} / ${s.date} 年代灵感</small><h1>${escapeHTML(s.title)}</h1><p>${escapeHTML(s.intro)}</p></header><figure><img src="images/memories/${s.image}.jpg" alt="${escapeHTML(s.title)}的怀旧创作配图"><figcaption>怀旧创作配图 · AI 辅助生成，非历史照片</figcaption></figure><div class="picture-story-text">${s.text.map(t=>`<p>${escapeHTML(t)}</p>`).join('')}</div><div class="story-ending">读完了，就早点睡。<small>明天还要去见喜欢的人。</small></div><footer><button data-phone-picture="${s.id}">在旧手机里再读一遍</button><a href="images/memories/${s.image}.jpg" download="${escapeHTML(s.title)}-怀旧创作.jpg">保存配图</a><button data-memory-gallery>继续翻图文</button><p>本站原创故事，不对应真实人物经历或历史原帖。</p></footer></article>`;}
function phoneGalleryMarkup(){if(!phonePicture)return `<div class="phone-wap-title">深夜图文馆</div>${pictureStories.map(s=>`<button class="phone-picture-entry" data-phone-picture="${s.id}"><img src="images/memories/${s.image}.jpg" alt="怀旧创作配图"><b>${escapeHTML(s.title)}</b><small>${s.tag} · 点图读故事</small></button>`).join('')}<p class="phone-small-note">原创故事 · AI 辅助配图<br>非历史原帖 / 照片</p>`;const s=pictureStories.find(x=>x.id===phonePicture);if(!s)return '';return `<div class="phone-picture-reading"><button data-phone-picture-back>‹ 图片目录</button><h2>${escapeHTML(s.title)}</h2><img src="images/memories/${s.image}.jpg" alt="怀旧创作配图"><small>原创图文 · 非历史原帖</small>${s.text.slice(phonePicturePage*2,phonePicturePage*2+2).map(t=>`<p>${escapeHTML(t)}</p>`).join('')}<div><button data-phone-picture-page="${phonePicturePage-1}" ${phonePicturePage===0?'disabled':''}>上一页</button><span>${phonePicturePage+1}/4</span><button data-phone-picture-page="${phonePicturePage+1}" ${phonePicturePage===3?'disabled':''}>下一页</button></div></div>`;}
document.addEventListener('submit',e=>{if(e.target.id!=='memory-search')return;e.preventDefault();galleryQuery=$('#memory-query').value.slice(0,80);navigate(current,false);});
document.addEventListener('click',e=>{const b=e.target.closest('[data-memory-gallery],[data-picture-story],[data-memory-tag],[data-memory-night],[data-phone-gallery],[data-phone-picture],[data-phone-picture-page],[data-phone-picture-back]');if(!b)return;e.preventDefault();if(b.hasAttribute('data-memory-gallery'))return openMemoryGallery();if(b.dataset.pictureStory)return openPictureStory(b.dataset.pictureStory);if(b.dataset.memoryTag){galleryTag=b.dataset.memoryTag;return navigate(current,false);}if(b.hasAttribute('data-memory-night')){galleryNight=!galleryNight;document.querySelectorAll('.picture-story,.memory-gallery').forEach(x=>x.classList.toggle('after-midnight',galleryNight));document.querySelectorAll('[data-memory-night]').forEach(x=>{x.textContent=galleryNight?'开灯':current.type==='pictures'?'熄灯看图':'熄灯';x.setAttribute('aria-pressed',String(galleryNight));});return;}if(b.hasAttribute('data-phone-gallery')){phonePicture=null;return openPhoneLab('gallery');}if(b.dataset.phonePicture&&pictureStories.some(s=>s.id===b.dataset.phonePicture)){phonePicture=b.dataset.phonePicture;phonePicturePage=0;if(current.type==='phone'){phoneState.app='gallery';refreshPhone();}else openPhoneLab('gallery');}if(b.dataset.phonePicturePage!==undefined){phonePicturePage=Math.max(0,Math.min(3,Number(b.dataset.phonePicturePage)||0));refreshPhone();}if(b.hasAttribute('data-phone-picture-back')){phonePicture=null;refreshPhone();}});

document.addEventListener('click',e=>{if(!e.target.closest('[data-memory-clear]'))return;galleryQuery='';galleryTag='全部';navigate(current,false);});
